var FALLBACK_STORIES = {"meta":{"accuracyNote":"Summaries paraphrase the Quranic narratives cited for each story. No quotations, events, dates, or hadith references have been invented. 'tradition' = 'quran' means the story is told in the cited verses; 'quran+scholarship' means the Quran gives a brief account and further detail comes from classical scholarly retellings — those details are labelled as such. The daily rotation is a reading schedule only; it does NOT claim any prophet's story happened on today's calendar date. Hadith references are intentionally omitted unless verified; add them only with a checked source.","count":40,"title":"Daily Prophets' Stories"},"stories":[{"context":"The Quran introduces Adam as the first human and the first prophet, taught the names of things and placed on earth as a trustee.","id":"s01","lessons":["Knowledge and learning are a trust, not a privilege.","Arrogance — refusing to bow when commanded — is the root of Iblis's fall.","Repentance is always open to the one who turns back sincerely."],"prophet":{"ar":"آدم","bn":"আদম","en":"Adam"},"quran":[{"name":"Al-Baqarah","surah":2,"verses":"30–39"}],"readingMinutes":4,"summary":"Allah created Adam, taught him the names of things, and commanded the angels to bow to him. Iblis refused out of pride. Adam and his wife were placed in the Garden with one command not to approach a particular tree.","title":"Adam — Creation and the Trust","titleBn":"আদম — সৃষ্টি ও আমানত","tradition":"quran"},{"context":"After eating from the forbidden tree, Adam and his wife acknowledged their wrongdoing and turned to Allah in repentance.","id":"s02","lessons":["Admitting a mistake is the first step back, not a defeat.","Blaming others prolongs the fall; owning it ends it.","Forgiveness follows sincere repentance."],"prophet":{"ar":"آدم","bn":"আদম","en":"Adam"},"quran":[{"name":"Al-A'raf","surah":7,"verses":"11–25"},{"name":"Ta-Ha","surah":20,"verses":"115–123"}],"readingMinutes":4,"summary":"Deceived by Iblis, Adam and his wife ate from the tree they had been warned about. They immediately confessed their wrongdoing and asked for forgiveness, and Allah accepted their repentance and guided them.","title":"Adam — The Fall and Repentance","titleBn":"আদম — পতন ও তওবা","tradition":"quran"},{"context":"The Quran tells of the two sons of Adam and the first murder on earth, a story about envy and the sanctity of life.","id":"s03","lessons":["Envy, left unchecked, grows into violence.","A sincere offering is accepted for its sincerity, not its size.","Every life is sacred; taking one unjustly is a grave wrong."],"prophet":{"ar":"ابنا آدم","bn":"আদমের দুই পুত্র","en":"Sons of Adam"},"quran":[{"name":"Al-Ma'idah","surah":5,"verses":"27–31"}],"readingMinutes":4,"summary":"Two sons of Adam each made an offering; one was accepted and the other was not. Consumed by envy, the rejected brother killed the accepted one, then learned — from a raven burying its dead — how to hide his brother's body, and was filled with remorse.","title":"The Two Sons of Adam — Envy and the First Wrongdoing","titleBn":"আদমের দুই পুত্র — হিংসা ও প্রথম অপরাধ","tradition":"quran"},{"context":"Idris is mentioned only briefly in the Quran, honoured as a truthful prophet raised to a high station.","id":"s04","lessons":["Truthfulness is itself a form of greatness.","A short mention in revelation is still an honour.","Steadfastness matters more than fame."],"prophet":{"ar":"إدريس","bn":"ইদরিস","en":"Idris"},"quran":[{"name":"Maryam","surah":19,"verses":"56–57"}],"readingMinutes":3,"summary":"The Quran describes Idris as a man of truth and a prophet, raised by Allah to a high station. Classical scholars retell his story as one of wisdom, patience and devotion; the Quran itself gives no further narrative detail.","title":"Idris — The Truthful Prophet","titleBn":"ইদরিস — সত্যবাদী নবী","tradition":"quran+scholarship"},{"context":"Nuh called his people for centuries to worship Allah alone. The Quran says he remained among them for 950 years.","id":"s05","lessons":["Persistence in a good cause is measured in decades, not days.","Mockery is not evidence that a message is false.","A caller must keep advising even when results are slow."],"prophet":{"ar":"نوح","bn":"নূহ","en":"Nuh"},"quran":[{"name":"Nuh","surah":71,"verses":"1–28"},{"name":"Hud","surah":11,"verses":"25–49"}],"readingMinutes":5,"summary":"Nuh warned his people night and day, in public and in private, but most of them plugged their ears and mocked him. Only a few believed. He prayed for guidance for his people until Allah commanded him to build the Ark.","title":"Nuh — Nine Hundred and Fifty Years of Calling","titleBn":"নূহ — সাড়ে নয়শো বছরের দাওয়াত","tradition":"quran"},{"context":"When the flood came, the Ark carried Nuh, the believers, and pairs of living creatures. His own son chose the mountain over the Ark and was lost.","id":"s06","lessons":["Salvation comes through obedience, not family ties.","Preparation before the crisis is what saves during it.","Even a prophet cannot save one who refuses to board."],"prophet":{"ar":"نوح","bn":"নূহ","en":"Nuh"},"quran":[{"name":"Hud","surah":11,"verses":"36–49"},{"name":"Al-Mu'minun","surah":23,"verses":"23–30"}],"readingMinutes":5,"summary":"Under Allah's command, Nuh built the Ark while his people laughed. When the flood came, the believers boarded with pairs of creatures. The waters covered the land, and the Ark came to rest. Nuh's son, who refused to board, was among those lost.","title":"Nuh — The Ark and the Flood","titleBn":"নূহ — নৌকা ও মহাপ্লাবন","tradition":"quran"},{"context":"Hud was sent to 'Ad, a powerful people famed for their strength and tall structures, who worshipped idols and oppressed others.","id":"s07","lessons":["Strength without gratitude becomes arrogance.","Prosperity is a test, not proof of being right.","A people's greatness is measured by justice, not buildings."],"prophet":{"ar":"هود","bn":"হুদ","en":"Hud"},"quran":[{"name":"Hud","surah":11,"verses":"50–60"},{"name":"Al-A'raf","surah":7,"verses":"65–72"}],"readingMinutes":4,"summary":"Hud called the people of 'Ad to worship Allah alone and abandon their idols. They boasted of their strength and demanded a sign. A barren wind came upon them for days, and the rejecting people were destroyed while Hud and the believers were saved.","title":"Hud — The People of 'Ad","titleBn":"হুদ — আদ জাতি","tradition":"quran"},{"context":"Salih was sent to Thamud, who carved homes into rock. He gave them a she-camel as a sign and warned them not to harm it.","id":"s08","lessons":["A clear sign does not help those who refuse to see.","Harming what Allah has protected invites ruin.","Wealth and skill cannot protect a people from their own injustice."],"prophet":{"ar":"صالح","bn":"সালেহ","en":"Salih"},"quran":[{"name":"Hud","surah":11,"verses":"61–68"},{"name":"Al-A'raf","surah":7,"verses":"73–79"}],"readingMinutes":4,"summary":"Salih called Thamud to Allah and gave them a she-camel as a sign, with the right to drink on appointed days. They hamstrung the camel despite the warning. After three days, a mighty blast seized them, and Salih and the believers were saved.","title":"Salih — The She-Camel","titleBn":"সালেহ — উষ্ট্রী","tradition":"quran"},{"context":"Young Ibrahim reasoned with his people against idol worship, then confronted the idols themselves in the temple.","id":"s09","lessons":["Truth can be spoken respectfully and still firmly.","An argument that exposes a contradiction is stronger than shouting.","Blind imitation of ancestors is not a proof."],"prophet":{"ar":"إبراهيم","bn":"ইবরাহিম","en":"Ibrahim"},"quran":[{"name":"Al-Anbiya","surah":21,"verses":"51–73"}],"readingMinutes":5,"summary":"Ibrahim asked his people why they worshipped idols that could neither hear nor help. When they were away, he broke the idols except the largest, then challenged them: if the idols could speak, let them say who did it. His people had no answer but anger.","title":"Ibrahim — Breaking the Idols","titleBn":"ইবরাহিম — মূর্তি ভাঙা","tradition":"quran"},{"context":"For breaking the idols, Ibrahim was thrown into a fire. Allah made the fire cool and safe for him.","id":"s10","lessons":["Courage means standing firm when the cost is real.","Allah's protection can come in the very place of danger.","A crowd's verdict is not Allah's verdict."],"prophet":{"ar":"إبراهيم","bn":"ইবরাহিম","en":"Ibrahim"},"quran":[{"name":"Al-Anbiya","surah":21,"verses":"68–70"},{"name":"As-Saffat","surah":37,"verses":"97–98"}],"readingMinutes":4,"summary":"Ibrahim's people decided to burn him for breaking their idols. They lit a great fire and cast him into it. Allah commanded the fire to be cool and safe, and Ibrahim emerged unharmed, while his persecutors' plan came to nothing.","title":"Ibrahim — The Fire Made Cool","titleBn":"ইবরাহিম — আগুন শীতল হওয়া","tradition":"quran"},{"context":"Ibrahim dreamed that he was sacrificing his son. Both father and son submitted, and Allah ransomed the son with a great sacrifice.","id":"s11","lessons":["Submission means trusting Allah even when the command is hard to bear.","A son's willingness honours a father's faith.","Relief comes at the very point of complete surrender."],"prophet":{"ar":"إبراهيم","bn":"ইবরাহিম","en":"Ibrahim"},"quran":[{"name":"As-Saffat","surah":37,"verses":"102–107"}],"readingMinutes":4,"summary":"Ibrahim told his son of the dream, and the son replied that his father should do as commanded and would find him patient. As Ibrahim prepared to act, Allah called out that the vision had been fulfilled, and ransomed the son with a mighty sacrifice.","title":"Ibrahim — The Sacrifice and the Son","titleBn":"ইবরাহিম — কুরবানি ও পুত্র","tradition":"quran"},{"context":"Ibrahim and Ismail raised the foundations of the House at Makkah and prayed that Allah accept it and make their descendants a submitting community.","id":"s12","lessons":["Building for Allah is completed with prayer, not pride.","A house of worship begins with a family working together.","Every good work should end with asking for acceptance."],"prophet":{"ar":"إبراهيم","bn":"ইবরাহিম","en":"Ibrahim"},"quran":[{"name":"Al-Baqarah","surah":2,"verses":"127–129"}],"readingMinutes":4,"summary":"Ibrahim and his son Ismail raised the foundations of the House, praying that Allah accept their work, teach their descendants the rites, and send them a messenger to recite the signs and purify them.","title":"Ibrahim — Building the House","titleBn":"ইবরাহিম — ঘর নির্মাণ","tradition":"quran"},{"context":"Lut called his people, who had fallen into shameful practices, to fear Allah and abandon their corruption.","id":"s13","lessons":["A prophet must speak against his own people's wrongdoing.","Hospitality and honouring guests are sacred duties.","When corruption is complete, leaving is obedience, not escape."],"prophet":{"ar":"لوط","bn":"লুত","en":"Lut"},"quran":[{"name":"Al-A'raf","surah":7,"verses":"80–84"},{"name":"Hud","surah":11,"verses":"77–83"}],"readingMinutes":4,"summary":"Lut warned his people against their shameful deeds, but they threatened to expel him. Angels came to him in human form; his people rushed to his house, and he pleaded with them to honour his guests. At dawn, his town was overturned, and Lut and the believers were saved.","title":"Lut — The Call to His People","titleBn":"লুত — তাঁর জাতির প্রতি আহ্বান","tradition":"quran"},{"context":"Ismail, left with his mother Hajar in a barren valley, became part of the story of Makkah and the well of Zamzam in classical retellings.","id":"s14","lessons":["Provision can appear where no cause is visible.","A mother's search and a child's thirst are remembered in rites of worship.","Trust in Allah turns a barren valley into a city."],"prophet":{"ar":"إسماعيل","bn":"ইসমাইল","en":"Ismail"},"quran":[{"name":"Al-Baqarah","surah":2,"verses":"127"},{"name":"Ibrahim","surah":14,"verses":"37"}],"readingMinutes":4,"summary":"The Quran records Ibrahim's prayer for the valley where he settled part of his family, asking that it be safe and provided for. Classical scholars retell how Hajar searched between the hills and how the well of Zamzam sprang forth — details that come from tradition, not from these verses themselves.","title":"Ismail — The Valley and the Well","titleBn":"ইসমাইল — উপত্যকা ও কূপ","tradition":"quran+scholarship"},{"context":"Ishaq was announced to Ibrahim and Sarah in their old age, a glad tiding that seemed impossible to them.","id":"s15","lessons":["Allah's promise is not bound by human calculations of age.","Good news may arrive when hope seems finished.","Gratitude for a child is part of the blessing itself."],"prophet":{"ar":"إسحاق","bn":"ইসহাক","en":"Ishaq"},"quran":[{"name":"Hud","surah":11,"verses":"69–73"},{"name":"As-Saffat","surah":37,"verses":"112–113"}],"readingMinutes":3,"summary":"Angels visiting Ibrahim brought glad tidings of a knowledgeable son. Sarah laughed in wonder, for she was old and her husband aged. The angels replied that this was Allah's decree, and Ishaq was born, a prophet among the righteous.","title":"Ishaq — The Glad Tidings","titleBn":"ইসহাক — সুসংবাদ","tradition":"quran"},{"context":"Yaqub, father of Yusuf, endured the loss of his beloved son and later his sight, yet never stopped trusting Allah.","id":"s16","lessons":["Grief and faith can live in the same heart.","A parent's patience can span decades without bitterness.","Hope in Allah does not expire with time."],"prophet":{"ar":"يعقوب","bn":"ইয়াকুব","en":"Yaqub"},"quran":[{"name":"Yusuf","surah":12,"verses":"83–87"},{"name":"Al-Baqarah","surah":2,"verses":"132–133"}],"readingMinutes":4,"summary":"When Yusuf was lost, Yaqub wept until he lost his sight, yet he told his sons never to despair of Allah's relief. Years later, when the truth came out, he forgave his sons and prayed for them, and his family was reunited in Egypt.","title":"Yaqub — Patience and Trust","titleBn":"ইয়াকুব — ধৈর্য ও ভরসা","tradition":"quran"},{"context":"As a boy, Yusuf dreamed that eleven stars, the sun and the moon bowed to him. His father warned him not to tell his brothers.","id":"s17","lessons":["A great dream should be guarded, not advertised.","Envy often begins among those closest to us.","A father's warning is itself a form of protection."],"prophet":{"ar":"يوسف","bn":"ইউসুফ","en":"Yusuf"},"quran":[{"name":"Yusuf","surah":12,"verses":"4–6"}],"readingMinutes":3,"summary":"Yusuf told his father Yaqub that he had seen eleven stars, the sun and the moon bowing down to him. Yaqub understood the dream's meaning, warned him not to recount it to his brothers lest envy stir them, and told him Allah would complete His favour upon him.","title":"Yusuf — The Dream","titleBn":"ইউসুফ — স্বপ্ন","tradition":"quran"},{"context":"Yusuf's brothers, jealous of their father's love, threw him into a well and told their father a wolf had eaten him.","id":"s18","lessons":["Jealousy can make brothers into strangers.","A lie needs a prop; truth needs only patience.","Even in a well, a boy can be under Allah's care."],"prophet":{"ar":"يوسف","bn":"ইউসুফ","en":"Yusuf"},"quran":[{"name":"Yusuf","surah":12,"verses":"7–22"}],"readingMinutes":5,"summary":"The brothers lured Yusuf away, cast him into a well, and stained his shirt with false blood. A caravan passing by drew him out and sold him in Egypt for a small price. In the house of his Egyptian master, Yusuf grew in wisdom and beauty.","title":"Yusuf — The Well and the Caravan","titleBn":"ইউসুফ — কূপ ও কাফেলা","tradition":"quran"},{"context":"In Egypt, Yusuf resisted temptation in his master's house and was imprisoned on a false charge, where he remained for years.","id":"s19","lessons":["Chastity is strength, not weakness.","A false charge can still lead to honour in the end.","Prison can become a school for a patient heart."],"prophet":{"ar":"يوسف","bn":"ইউসুফ","en":"Yusuf"},"quran":[{"name":"Yusuf","surah":12,"verses":"23–35"}],"readingMinutes":5,"summary":"The wife of Yusuf's master tried to seduce him; he refused and fled, and the torn shirt proved his innocence — yet he was imprisoned to protect reputations. In prison he called his fellow inmates to Allah and interpreted their dreams with a clarity that amazed them.","title":"Yusuf — Trials in Egypt","titleBn":"ইউসুফ — মিসরে পরীক্ষা","tradition":"quran"},{"context":"The king dreamed of seven fat cows eaten by seven lean ones, and seven green ears of grain and seven dry. Yusuf interpreted the dream and planned for the famine.","id":"s20","lessons":["Knowledge is most valuable when it serves people in need.","Planning for hardship is part of trust, not a lack of it.","A gift used for the common good becomes a public trust."],"prophet":{"ar":"يوسف","bn":"ইউসুফ","en":"Yusuf"},"quran":[{"name":"Yusuf","surah":12,"verses":"36–49"}],"readingMinutes":5,"summary":"When the king's dream baffled his courtiers, Yusuf — still in prison — interpreted it: seven years of plenty would be followed by seven years of famine, and advised storing grain during the good years. The king, impressed, summoned him and placed him in charge of the storehouses.","title":"Yusuf — Interpreting Dreams","titleBn":"ইউসুফ — স্বপ্নের ব্যাখ্যা","tradition":"quran"},{"context":"During the famine, Yusuf's brothers came to Egypt for grain. He tested them, revealed himself, and forgave them completely.","id":"s21","lessons":["Forgiveness after power is the highest form of strength.","A wrong can be repaired without humiliating the wrongdoer.","Family bonds can survive even betrayal."],"prophet":{"ar":"يوسف","bn":"ইউসুফ","en":"Yusuf"},"quran":[{"name":"Yusuf","surah":12,"verses":"58–101"}],"readingMinutes":6,"summary":"The brothers came seeking grain and did not recognise the minister before them. Yusuf tested them, then revealed himself: 'I am Yusuf, and this is my brother.' He forgave them without reproach, brought his parents to Egypt, and thanked Allah for the dream's fulfilment.","title":"Yusuf — Reunion and Forgiveness","titleBn":"ইউসুফ — পুনর্মিলন ও ক্ষমা","tradition":"quran"},{"context":"Ayyub lost his wealth, his children and his health, yet remained patient and turned to Allah in prayer.","id":"s22","lessons":["Patience is not the absence of pain but endurance through it.","Calling on Allah in affliction is itself worship.","Relief, when it comes, can exceed what was lost."],"prophet":{"ar":"أيوب","bn":"আইয়ুব","en":"Ayyub"},"quran":[{"name":"Al-Anbiya","surah":21,"verses":"83–84"},{"name":"Sad","surah":38,"verses":"41–44"}],"readingMinutes":4,"summary":"Ayyub endured prolonged affliction and called upon Allah, saying that hardship had touched him and Allah is the Most Merciful. Allah answered him, removed his affliction, and restored his family and wealth as a mercy and a reminder for worshippers.","title":"Ayyub — Patience in Affliction","titleBn":"আইয়ুব — বিপদে ধৈর্য","tradition":"quran"},{"context":"Shuaib was sent to Midian, whose people cheated in trade and blocked the roads. He called them to fair measure and honest dealing.","id":"s23","lessons":["Honesty in business is part of faith, not separate from it.","Cheating customers is corruption, however small the measure.","A community's economy reflects its morals."],"prophet":{"ar":"شعيب","bn":"শুয়াইব","en":"Shuaib"},"quran":[{"name":"Hud","surah":11,"verses":"84–95"},{"name":"Al-A'raf","surah":7,"verses":"85–93"}],"readingMinutes":4,"summary":"Shuaib told his people to give full measure and weight, not to defraud others, and not to spread corruption. They mocked him and threatened him, but he persisted. A mighty blast seized the rejecters, and Shuaib and the believers were saved.","title":"Shuaib — Honest Measure","titleBn":"শুয়াইব — সঠিক মাপ","tradition":"quran"},{"context":"Musa, tending flocks in Midian, saw a fire on the mountain and found himself addressed by Allah from a blessed valley.","id":"s24","lessons":["A call can come in the middle of ordinary work.","Remove distractions — even sandals — before sacred words.","Fear can turn into strength when Allah says, 'Do not fear.'"],"prophet":{"ar":"موسى","bn":"মুসা","en":"Musa"},"quran":[{"name":"Ta-Ha","surah":20,"verses":"9–36"},{"name":"Al-Qasas","surah":28,"verses":"29–35"}],"readingMinutes":5,"summary":"Musa saw a fire and went to it hoping for a brand or guidance. From the fire came the voice: 'I am Allah.' His staff became a serpent and his hand shone white. He asked for his brother Harun as a helper, and Allah granted it, sending them both to Pharaoh.","title":"Musa — The Burning Bush","titleBn":"মুসা — জ্বলন্ত ঝোপ","tradition":"quran"},{"context":"Musa and Harun confronted Pharaoh, who claimed divinity and enslaved the Israelites. The contest with Pharaoh's magicians ended with the magicians believing.","id":"s25","lessons":["Truth does not need Pharaoh's permission to be spoken.","Even hired opponents can recognise truth when they see it.","Tyranny's first response to truth is mockery, then force."],"prophet":{"ar":"موسى","bn":"মুসা","en":"Musa"},"quran":[{"name":"Al-A'raf","surah":7,"verses":"103–126"},{"name":"Ta-Ha","surah":20,"verses":"56–73"}],"readingMinutes":5,"summary":"Musa showed Pharaoh the signs — the staff that became a serpent and the shining hand — but Pharaoh called it magic and summoned his magicians. Their ropes and staffs seemed to move, but Musa's staff swallowed them. The magicians fell down believing, though Pharaoh threatened them with punishment.","title":"Musa — Before Pharaoh","titleBn":"মুসা — ফেরাউনের সামনে","tradition":"quran"},{"context":"Pharaoh's army pursued the Israelites to the sea. Allah parted the waters, the Israelites crossed, and Pharaoh's host drowned.","id":"s26","lessons":["When every road is closed, the sea itself can open.","A pursuer's power ends where Allah's command begins.","Deliverance and destruction can happen in the same waters."],"prophet":{"ar":"موسى","bn":"মুসা","en":"Musa"},"quran":[{"name":"Ta-Ha","surah":20,"verses":"77–82"},{"name":"Ash-Shu'ara","surah":26,"verses":"52–68"}],"readingMinutes":5,"summary":"By Allah's command, Musa led his people out by night. At the sea, with Pharaoh's army behind them, the people despaired, but Musa struck the sea and it parted into dry paths. The Israelites crossed safely; Pharaoh and his army, following in, were drowned.","title":"Musa — The Exodus and the Sea","titleBn":"মুসা — সমুদ্র পারাপার","tradition":"quran"},{"context":"While Musa was on the mountain receiving the tablets, some of his people made a golden calf and worshipped it.","id":"s27","lessons":["A community can relapse the moment its leader is absent.","Gold can become an idol when patience runs out.","A leader's anger must be followed by intercession, not abandonment."],"prophet":{"ar":"موسى","bn":"মুসা","en":"Musa"},"quran":[{"name":"Ta-Ha","surah":20,"verses":"83–98"},{"name":"Al-A'raf","surah":7,"verses":"148–154"}],"readingMinutes":5,"summary":"Musa went to the mountain for forty nights. In his absence, Samiri made a calf from the people's gold, and many worshipped it. Musa returned in anger, seized Harun, and then prayed for forgiveness for himself and his brother. The calf was burned and scattered in the sea.","title":"Musa — The Golden Calf","titleBn":"মুসা — সোনার বাছুর","tradition":"quran"},{"context":"Harun, Musa's brother, shared the mission: he spoke for Musa, stayed with the people, and bore their pressure with patience.","id":"s28","lessons":["A helper's role is itself a prophetic honour.","Speaking for truth takes a different courage than leading.","Restraint under pressure can be wiser than force."],"prophet":{"ar":"هارون","bn":"হারুন","en":"Harun"},"quran":[{"name":"Ta-Ha","surah":20,"verses":"29–36"},{"name":"Al-A'raf","surah":7,"verses":"142"}],"readingMinutes":4,"summary":"Musa asked Allah to make Harun his minister, to strengthen him and share his task. Harun stood beside Musa before Pharaoh and stayed with the people when Musa went to the mountain, counselling patience when they turned to the calf.","title":"Harun — The Brother and Helper","titleBn":"হারুন — ভাই ও সহযোগী","tradition":"quran"},{"context":"Dawud, a shepherd who became king, was given the Zabur and a voice so beautiful that mountains and birds joined his praise.","id":"s29","lessons":["Leadership and devotion belong together.","Justice must be judged by evidence, even against oneself.","A beautiful voice is a trust to be used in praise, not pride."],"prophet":{"ar":"داود","bn":"দাউদ","en":"Dawud"},"quran":[{"name":"Sad","surah":38,"verses":"17–26"},{"name":"Al-Baqarah","surah":2,"verses":"251"}],"readingMinutes":4,"summary":"Dawud was given wisdom, kingship and the Zabur. The Quran recalls his repentance after judging a dispute between two litigants, and how Allah strengthened his kingdom. His praise was joined, in the Quran's imagery, by mountains and birds.","title":"Dawud — The Psalmist King","titleBn":"দাউদ — জাবুরের নবী ও বাদশাহ","tradition":"quran"},{"context":"Sulayman understood the speech of birds and, passing through a valley of ants, smiled at an ant's warning to its colony.","id":"s30","lessons":["Power is complete only when it listens to the smallest voices.","A smile at a small creature shows a great heart.","Gratitude for a gift is part of the gift itself."],"prophet":{"ar":"سليمان","bn":"সুলাইমান","en":"Sulayman"},"quran":[{"name":"An-Naml","surah":27,"verses":"15–19"}],"readingMinutes":3,"summary":"Sulayman, heir to Dawud, was taught the speech of birds and marched with armies of jinn, humans and birds. In a valley of ants, he heard an ant warn its fellows to enter their dwellings lest Sulayman's hosts crush them unknowingly — and he smiled and thanked Allah for His favour.","title":"Sulayman — Wisdom and the Ant Valley","titleBn":"সুলাইমান — পিঁপড়ের উপত্যকা","tradition":"quran"},{"context":"Sulayman received word of a queen in Sheba who worshipped the sun. He invited her to Allah, and she came and submitted.","id":"s31","lessons":["Diplomacy can precede force, and often replaces it.","A wise ruler tests reports before acting on them.","Submission to truth is not defeat but dignity."],"prophet":{"ar":"سليمان","bn":"সুলাইমান","en":"Sulayman"},"quran":[{"name":"An-Naml","surah":27,"verses":"20–44"}],"readingMinutes":5,"summary":"The hoopoe brought Sulayman news of a queen ruling Sheba, whose people worshipped the sun. Sulayman sent her a letter inviting submission. She came, recognised the signs, and declared her submission to Allah with Sulayman, after mistaking his glass palace floor for water.","title":"Sulayman — The Queen of Sheba","titleBn":"সুলাইমান — সাবার রানি","tradition":"quran"},{"context":"Ilyas called his people, who worshipped Baal, back to Allah, but they rejected him.","id":"s32","lessons":["Calling people away from inherited idols is lonely work.","A prophet's success is not measured by the crowd's response.","Patience with a rejecting people is itself faithfulness."],"prophet":{"ar":"إلياس","bn":"ইলিয়াস","en":"Ilyas"},"quran":[{"name":"As-Saffat","surah":37,"verses":"123–132"}],"readingMinutes":3,"summary":"Ilyas told his people to fear Allah and abandon Baal, the idol they worshipped, but they called him a liar. The Quran records that he was left with a good name among later generations, while those who rejected the message faced its consequence.","title":"Ilyas — The Call to His People","titleBn":"ইলিয়াস — তাঁর জাতির প্রতি আহ্বান","tradition":"quran"},{"context":"Al-Yasa is named in the Quran among the righteous prophets, a successor in the line of guidance.","id":"s33","lessons":["Continuing a predecessor's work is itself a prophetic task.","The Quran honours some prophets with a name and no long story.","Steadfastness in an unrecorded life is still recorded with Allah."],"prophet":{"ar":"اليسع","bn":"আল-ইয়াসা","en":"Al-Yasa"},"quran":[{"name":"Sad","surah":38,"verses":"48"},{"name":"Al-An'am","surah":6,"verses":"86"}],"readingMinutes":3,"summary":"Al-Yasa is mentioned in the Quran among the excellent and righteous, alongside Ismail and Dhul-Kifl. No extended narrative about him is given in the Quran; classical scholars place him as a successor carrying on the guidance of Ilyas.","title":"Al-Yasa — The Successor","titleBn":"আল-ইয়াসা — উত্তরসূরি","tradition":"quran+scholarship"},{"context":"Yunus left his people in anger before their punishment came, was swallowed by a great fish, and called out from the darkness.","id":"s34","lessons":["Leaving a task in anger is itself a mistake to repent.","Darkness — of sea, night and belly — cannot hide a sincere call.","A whole city's repentance can turn away punishment."],"prophet":{"ar":"يونس","bn":"ইউনুস","en":"Yunus"},"quran":[{"name":"As-Saffat","surah":37,"verses":"139–148"},{"name":"Al-Anbiya","surah":21,"verses":"87–88"}],"readingMinutes":5,"summary":"Yunus departed from his people before permission came and boarded a laden ship. Cast into the sea, he was swallowed by a great fish and called out from the darkness, glorifying Allah and confessing his wrong. He was cast onto the shore, and his people — who had believed — were granted respite.","title":"Yunus — The Man of the Whale","titleBn":"ইউনুস — মাছের মানুষ","tradition":"quran"},{"context":"Dhul-Kifl is named in the Quran among the patient and righteous, though no story about him is narrated there.","id":"s35","lessons":["Patience is a rank, not just a feeling.","Some of the righteous are known to Allah by a name alone.","Keeping a trust faithfully is a form of prophecy's work."],"prophet":{"ar":"ذو الكفل","bn":"জুলকিফল","en":"Dhul-Kifl"},"quran":[{"name":"Al-Anbiya","surah":21,"verses":"85–86"},{"name":"Sad","surah":38,"verses":"48"}],"readingMinutes":3,"summary":"Dhul-Kifl is mentioned in the Quran among the patient and the righteous, together with Ismail and Idris. The Quran gives no further narrative about him; classical scholars offer various identifications, which are not settled by the Quranic text itself.","title":"Dhul-Kifl — The Patient One","titleBn":"জুলকিফল — ধৈর্যশীল","tradition":"quran+scholarship"},{"context":"Zakariya, old and childless, prayed privately for an heir, and was given Yahya.","id":"s36","lessons":["Private prayer is not less powerful than public prayer.","Old age does not close the door of Allah's gift.","An answered prayer should be met with more devotion, not less."],"prophet":{"ar":"زكريا","bn":"জাকারিয়া","en":"Zakariya"},"quran":[{"name":"Maryam","surah":19,"verses":"2–15"},{"name":"Al-Anbiya","surah":21,"verses":"89–90"}],"readingMinutes":4,"summary":"Zakariya called upon Allah in secret, asking for an heir despite his old age and his wife's barrenness. Angels gave him glad tidings of Yahya, a name never given before. He asked for a sign and was told he would not speak to people for three nights, though sound.","title":"Zakariya — A Prayer Answered","titleBn":"জাকারিয়া — কবুল হওয়া দোয়া","tradition":"quran"},{"context":"Yahya, son of Zakariya, was given wisdom as a youth, and is described as chaste, dutiful to his parents, and not arrogant.","id":"s37","lessons":["Wisdom can come early to a pure heart.","Dutifulness to parents is part of prophethood's character.","Chastity and humility are strengths, not softness."],"prophet":{"ar":"يحيى","bn":"ইয়াহিয়া","en":"Yahya"},"quran":[{"name":"Maryam","surah":19,"verses":"12–15"}],"readingMinutes":3,"summary":"The Quran says Yahya was given wisdom while still a boy, and describes him as compassionate, pure, dutiful to his parents, and neither arrogant nor rebellious. Peace is pronounced upon him on the day he was born, the day he dies, and the day he is raised alive.","title":"Yahya — The Chaste Prophet","titleBn":"ইয়াহিয়া — পবিত্র নবী","tradition":"quran"},{"context":"Maryam, alone and in labour, was told not to grieve; a stream and ripe dates were provided for her, and her child spoke from the cradle.","id":"s38","lessons":["Provision can come to the one who is most alone.","A mother's dignity is defended by Allah Himself.","A miracle does not remove the hardship around it."],"prophet":{"ar":"عيسى","bn":"ঈসা","en":"Isa"},"quran":[{"name":"Maryam","surah":19,"verses":"16–36"}],"readingMinutes":5,"summary":"Maryam withdrew to a distant place and gave birth beneath a palm tree. She was told to shake the trunk for ripe dates and to drink from a stream. When her people questioned her, the infant Isa spoke from the cradle, declaring himself a servant of Allah, a prophet given the Book.","title":"Isa — The Birth","titleBn":"ঈসা — জন্ম","tradition":"quran"},{"context":"Isa was given the Gospel, healed the blind and the leper, and raised the dead by Allah's permission, calling his people to worship Allah alone.","id":"s39","lessons":["Miracles point to Allah; they are not ends in themselves.","A prophet's message is worship of Allah alone.","Gratitude for a gift is shown by using it for others."],"prophet":{"ar":"عيسى","bn":"ঈসা","en":"Isa"},"quran":[{"name":"Al-Imran","surah":3,"verses":"45–59"},{"name":"Al-Ma'idah","surah":5,"verses":"110–120"}],"readingMinutes":5,"summary":"The Quran describes Isa as the Messiah, a word from Allah, strengthened with the Holy Spirit. He fashioned a bird from clay and breathed life into it by Allah's permission, healed the blind and the leper, and raised the dead — all as signs, while calling his people to worship Allah, his Lord and theirs.","title":"Isa — Miracles and Message","titleBn":"ঈসা — মুজিজা ও বাণী","tradition":"quran"},{"context":"In the cave of Hira, Muhammad received the first words of revelation: a command to read in the name of his Lord who created.","id":"s40","lessons":["The first command of revelation is to read and learn.","A mission can begin in solitude, far from crowds.","Trembling at a great encounter is human; returning to it is faith."],"prophet":{"ar":"محمد","bn":"মুহাম্মদ","en":"Muhammad"},"quran":[{"name":"Al-Alaq","surah":96,"verses":"1–5"},{"name":"Al-Muddaththir","surah":74,"verses":"1–7"}],"readingMinutes":4,"summary":"The Quran's first revealed words commanded reading in the name of the Lord who created humanity from a clinging clot, who taught by the pen and taught humanity what it did not know. Classical accounts describe this moment in the cave of Hira, where the Prophet received the revelation and returned home deeply moved.","title":"Muhammad — The First Revelation","titleBn":"মুহাম্মদ — প্রথম ওহি","tradition":"quran+scholarship"}]};
var FALLBACK_STORIES_BN = {"meta":{"accuracyNote":"Bengali translation of the English stories dataset. Same source policy: summaries paraphrase the cited Quranic passages; no quotations, events, dates or hadith references invented; 'quran+scholarship' means the Quran gives a brief account and further detail comes from classical scholarly retellings. The daily rotation is a reading schedule only, not a historical anniversary claim.","count":40,"title":"Daily Prophets' Stories (Bengali)"},"stories":[{"context":"কুরআনে আদমকে প্রথম মানুষ ও প্রথম নবী হিসেবে পরিচয় দেওয়া হয়েছে — তাঁকে জিনিসের নাম শেখানো হয়েছিল এবং পৃথিবীতে প্রতিনিধি হিসেবে রাখা হয়েছিল।","id":"s01","lessons":["জ্ঞান ও শিক্ষা আমানত, সুযোগ নয়।","অহংকার — আদেশ পেয়েও সিজদা না করা — ইবলিসের পতনের মূল।","আন্তরিকভাবে ফিরে এলে তওবার দরজা সবসময় খোলা।"],"prophet":{"ar":"آدم","bn":"আদম","en":"আদম"},"quran":[{"name":"Al-Baqarah","surah":2,"verses":"30–39"}],"readingMinutes":4,"summary":"আল্লাহ আদমকে সৃষ্টি করলেন, সব জিনিসের নাম শেখালেন এবং ফেরেশতাদের তাঁকে সিজদা করতে বললেন। ইবলিস অহংকার করে অস্বীকার করল। আদম ও তাঁর স্ত্রীকে জান্নাতে রাখা হলো, শুধু একটি গাছের কাছে যেতে নিষেধ করা হলো।","title":"আদম — সৃষ্টি ও আমানত","titleBn":"আদম — সৃষ্টি ও আমানত","tradition":"quran"},{"context":"নিষিদ্ধ গাছের ফল খাওয়ার পর আদম ও তাঁর স্ত্রী নিজেদের ভুল স্বীকার করে আল্লাহর কাছে তওবা করলেন।","id":"s02","lessons":["ভুল স্বীকার করাই ফিরে আসার প্রথম ধাপ, পরাজয় নয়।","অন্যকে দোষ দিলে পতন দীর্ঘ হয়; নিজের ভুল মানলে তা শেষ হয়।","আন্তরিক তওবার পর ক্ষমা আসে।"],"prophet":{"ar":"آدم","bn":"আদম","en":"আদম"},"quran":[{"name":"Al-A'raf","surah":7,"verses":"11–25"},{"name":"Ta-Ha","surah":20,"verses":"115–123"}],"readingMinutes":4,"summary":"ইবলিসের ধোঁকায় আদম ও তাঁর স্ত্রী নিষিদ্ধ গাছের ফল খেলেন। তাঁরা সঙ্গে সঙ্গে নিজেদের ভুল স্বীকার করে ক্ষমা চাইলেন, আর আল্লাহ তাঁদের তওবা কবুল করে পথ দেখালেন।","title":"আদম — পতন ও তওবা","titleBn":"আদম — পতন ও তওবা","tradition":"quran"},{"context":"কুরআনে আদমের দুই পুত্রের ঘটনা বলা হয়েছে — পৃথিবীতে প্রথম হত্যা, হিংসা ও জীবনের পবিত্রতা নিয়ে।","id":"s03","lessons":["হিংসা নিয়ন্ত্রণ না করলে তা সহিংসতায় পরিণত হয়।","আন্তরিক কুরবানি তার আন্তরিকতার জন্য কবুল হয়, আকারের জন্য নয়।","প্রতিটি জীবন পবিত্র; অন্যায়ভাবে প্রাণ নেওয়া গুরুতর অপরাধ।"],"prophet":{"ar":"ابنا آدم","bn":"আদমের দুই পুত্র","en":"আদমের দুই পুত্র"},"quran":[{"name":"Al-Ma'idah","surah":5,"verses":"27–31"}],"readingMinutes":4,"summary":"আদমের দুই পুত্র দুটি কুরবানি দিলেন; একজনেরটি কবুল হলো, অন্যজনেরটি হলো না। হিংসায় ভরে প্রত্যাখ্যাত ভাই কবুল হওয়া ভাইকে হত্যা করল, তারপর একটি কাককে মৃতদেহ মাটি চাপা দিতে দেখে নিজের ভাইয়ের দেহ কীভাবে লুকাবে তা শিখল এবং অনুতপ্ত হলো।","title":"আদমের দুই পুত্র — হিংসা ও প্রথম অপরাধ","titleBn":"আদমের দুই পুত্র — হিংসা ও প্রথম অপরাধ","tradition":"quran"},{"context":"ইদরিসের কথা কুরআনে খুব সংক্ষেপে এসেছে — তাঁকে সত্যবাদী নবী হিসেবে সম্মানিত করে উঁচু মর্যাদা দেওয়া হয়েছিল।","id":"s04","lessons":["সত্যবাদিতা নিজেই এক ধরনের মহত্ত্ব।","কুরআনে সংক্ষিপ্ত উল্লেখও সম্মানের বিষয়।","খ্যাতির চেয়ে অবিচল থাকা বেশি মূল্যবান।"],"prophet":{"ar":"إدريس","bn":"ইদরিস","en":"ইদরিস"},"quran":[{"name":"Maryam","surah":19,"verses":"56–57"}],"readingMinutes":3,"summary":"কুরআনে ইদরিসকে সত্যবাদী মানুষ ও নবী বলা হয়েছে, আল্লাহ তাঁকে উঁচু মর্যাদায় তুলেছিলেন। ধ্রুপদী আলেমরা তাঁর কাহিনী জ্ঞান, ধৈর্য ও ইবাদতের গল্প হিসেবে বর্ণনা করেন; কুরআনে এর বেশি বিস্তারিত আসেনি।","title":"ইদরিস — সত্যবাদী নবী","titleBn":"ইদরিস — সত্যবাদী নবী","tradition":"quran+scholarship"},{"context":"নূহ তাঁর জাতিকে এক আল্লাহর ইবাদতের দিকে ডেকেছিলেন বহু শতাব্দী ধরে। কুরআন বলে, তিনি তাঁদের মাঝে ৯৫০ বছর ছিলেন।","id":"s05","lessons":["ভালো কাজের চেষ্টা দিনে নয়, দশকে মাপা হয়।","ঠাট্টা প্রমাণ করে না যে বাণী মিথ্যা।","ফল ধীরে এলেও উপদেশ দিয়ে যেতে হয়।"],"prophet":{"ar":"نوح","bn":"নূহ","en":"নূহ"},"quran":[{"name":"Nuh","surah":71,"verses":"1–28"},{"name":"Hud","surah":11,"verses":"25–49"}],"readingMinutes":5,"summary":"নূহ তাঁর জাতিকে রাতে-দিনে, প্রকাশ্যে-গোপনে সতর্ক করলেন, কিন্তু বেশিরভাগ মানুষ কানে আঙুল দিয়ে ঠাট্টা করল। মাত্র কয়েকজন ঈমান আনল। তিনি তাঁদের জন্য দোয়া করতে থাকলেন, যতক্ষণ না আল্লাহ তাঁকে নৌকা বানাতে আদেশ দিলেন।","title":"নূহ — সাড়ে নয়শো বছরের দাওয়াত","titleBn":"নূহ — সাড়ে নয়শো বছরের দাওয়াত","tradition":"quran"},{"context":"প্লাবন এলে নৌকায় উঠলেন নূহ, মুমিনরা এবং প্রতিটি প্রাণীর জোড়া। তাঁর নিজের ছেলে নৌকার বদলে পাহাড় বেছে নিয়ে হারিয়ে গেল।","id":"s06","lessons":["মুক্তি আসে আনুগত্য দিয়ে, আত্মীয়তা দিয়ে নয়।","সংকটের আগের প্রস্তুতিই সংকটে বাঁচায়।","যে উঠতে অস্বীকার করে, নবীও তাকে বাঁচাতে পারেন না।"],"prophet":{"ar":"نوح","bn":"নূহ","en":"নূহ"},"quran":[{"name":"Hud","surah":11,"verses":"36–49"},{"name":"Al-Mu'minun","surah":23,"verses":"23–30"}],"readingMinutes":5,"summary":"আল্লাহর আদেশে নূহ নৌকা বানালেন, আর তাঁর জাতি হাসল। প্লাবন এলে মুমিনরা প্রাণীর জোড়াসহ নৌকায় উঠলেন। পানি সব ঢেকে দিল, নৌকা থামল। নূহের ছেলে, যে উঠতে অস্বীকার করেছিল, হারিয়ে যাওয়া লোকদের মধ্যে ছিল।","title":"নূহ — নৌকা ও মহাপ্লাবন","titleBn":"নূহ — নৌকা ও মহাপ্লাবন","tradition":"quran"},{"context":"হুদকে পাঠানো হয়েছিল আদ জাতির কাছে — শক্তি ও উঁচু স্থাপত্যের জন্য বিখ্যাত এক জাতি, যারা মূর্তি পূজা করত ও জুলুম করত।","id":"s07","lessons":["কৃতজ্ঞতা ছাড়া শক্তি অহংকারে পরিণত হয়।","সমৃদ্ধি পরীক্ষা, সঠিক হওয়ার প্রমাণ নয়।","জাতির মহত্ত্ব ভবন দিয়ে নয়, ন্যায় দিয়ে মাপা হয়।"],"prophet":{"ar":"هود","bn":"হুদ","en":"হুদ"},"quran":[{"name":"Hud","surah":11,"verses":"50–60"},{"name":"Al-A'raf","surah":7,"verses":"65–72"}],"readingMinutes":4,"summary":"হুদ আদ জাতিকে এক আল্লাহর ইবাদত করতে ও মূর্তি ছাড়তে ডাকলেন। তারা নিজেদের শক্তির বড়াই করল ও নিদর্শন দাবি করল। কয়েক দিন ধরে এক বন্ধ্যা বাতাস তাদের ওপর এলো, অস্বীকারকারীরা ধ্বংস হলো, আর হুদ ও মুমিনরা বেঁচে গেলেন।","title":"হুদ — আদ জাতি","titleBn":"হুদ — আদ জাতি","tradition":"quran"},{"context":"সালেহকে পাঠানো হয়েছিল সামুদ জাতির কাছে, যারা পাহাড় কেটে ঘর বানাত। তিনি তাদের একটি উষ্ট্রীকে নিদর্শন হিসেবে দিলেন এবং ক্ষতি করতে নিষেধ করলেন।","id":"s08","lessons":["স্পষ্ট নিদর্শনও তাদের সাহায্য করে না যারা দেখতে অস্বীকার করে।","আল্লাহ যা রক্ষা করেছেন তার ক্ষতি করা ধ্বংস ডেকে আনে।","ধন ও দক্ষতা কোনো জাতিকে নিজের জুলুম থেকে বাঁচাতে পারে না।"],"prophet":{"ar":"صالح","bn":"সালেহ","en":"সালেহ"},"quran":[{"name":"Hud","surah":11,"verses":"61–68"},{"name":"Al-A'raf","surah":7,"verses":"73–79"}],"readingMinutes":4,"summary":"সালেহ সামুদকে আল্লাহর দিকে ডাকলেন এবং উষ্ট্রীকে নিদর্শন হিসেবে দিলেন — নির্দিষ্ট দিনে তার পানির অধিকার ছিল। সতর্ক করা সত্ত্বেও তারা উষ্ট্রীর পা কেটে দিল। তিন দিন পর এক প্রচণ্ড শব্দ তাদের পাকড়াও করল, আর সালেহ ও মুমিনরা বেঁচে গেলেন।","title":"সালেহ — উষ্ট্রী","titleBn":"সালেহ — উষ্ট্রী","tradition":"quran"},{"context":"তরুণ ইবরাহিম তাঁর জাতির মূর্তিপূজার বিরুদ্ধে যুক্তি দিলেন, তারপর মন্দিরে গিয়ে মূর্তিগুলোর মুখোমুখি হলেন।","id":"s09","lessons":["সত্য সম্মানের সাথে, তবু দৃঢ়ভাবে বলা যায়।","বিরোধিতা ফাঁস করে দেওয়া যুক্তি চিৎকারের চেয়ে শক্তিশালী।","পূর্বপুরুষের অন্ধ অনুকরণ কোনো প্রমাণ নয়।"],"prophet":{"ar":"إبراهيم","bn":"ইবরাহিম","en":"ইবরাহিম"},"quran":[{"name":"Al-Anbiya","surah":21,"verses":"51–73"}],"readingMinutes":5,"summary":"ইবরাহিম তাঁর জাতিকে জিজ্ঞেস করলেন, কেন তারা এমন মূর্তি পূজা করে যা শুনতেও পারে না, সাহায্যও করতে পারে না। তারা দূরে থাকতে তিনি সবচেয়ে বড়টি ছাড়া বাকি মূর্তি ভেঙে দিলেন, তারপর তাদের চ্যালেঞ্জ করলেন: মূর্তিগুলো কথা বলতে পারলে বলুক কে এটা করেছে। তাঁর জাতির কাছে রাগ ছাড়া আর কোনো উত্তর ছিল না।","title":"ইবরাহিম — মূর্তি ভাঙা","titleBn":"ইবরাহিম — মূর্তি ভাঙা","tradition":"quran"},{"context":"মূর্তি ভাঙার জন্য ইবরাহিমকে আগুনে ফেলা হয়েছিল। আল্লাহ আগুনকে তাঁর জন্য শীতল ও নিরাপদ করে দিলেন।","id":"s10","lessons":["সাহস মানে মূল্য বাস্তব হলেও অটল থাকা।","আল্লাহর সুরক্ষা বিপদের জায়গাতেই আসতে পারে।","জনতার রায় আল্লাহর রায় নয়।"],"prophet":{"ar":"إبراهيم","bn":"ইবরাহিম","en":"ইবরাহিম"},"quran":[{"name":"Al-Anbiya","surah":21,"verses":"68–70"},{"name":"As-Saffat","surah":37,"verses":"97–98"}],"readingMinutes":4,"summary":"ইবরাহিমের জাতি তাঁকে পোড়ানোর সিদ্ধান্ত নিল। তারা বড় আগুন জ্বালিয়ে তাঁকে তাতে ফেলল। আল্লাহ আগুনকে শীতল ও নিরাপদ হতে বললেন, ইবরাহিম অক্ষত বেরিয়ে এলেন, আর তাঁর অত্যাচারীদের পরিকল্পনা ব্যর্থ হলো।","title":"ইবরাহিম — আগুন শীতল হওয়া","titleBn":"ইবরাহিম — আগুন শীতল হওয়া","tradition":"quran"},{"context":"ইবরাহিম স্বপ্নে দেখলেন তিনি তাঁর ছেলেকে কুরবানি করছেন। বাবা ও ছেলে দুজনেই আত্মসমর্পণ করলেন, আর আল্লাহ ছেলের বদলে এক মহান কুরবানি দিলেন।","id":"s11","lessons":["আত্মসমর্পণ মানে আদেশ কঠিন মনে হলেও আল্লাহর ওপর ভরসা করা।","ছেলের সম্মতি বাবার ঈমানকে সম্মানিত করে।","পূর্ণ আত্মসমর্পণের মুহূর্তেই মুক্তি আসে।"],"prophet":{"ar":"إبراهيم","bn":"ইবরাহিম","en":"ইবরাহিম"},"quran":[{"name":"As-Saffat","surah":37,"verses":"102–107"}],"readingMinutes":4,"summary":"ইবরাহিম ছেলেকে স্বপ্নের কথা বললেন, ছেলে বলল বাবা যেন আদেশমতো কাজ করেন — তিনি তাঁকে ধৈর্যশীল পাবেন। ইবরাহিম কাজ করতে উদ্যত হলে আল্লাহ ডাক দিলেন যে স্বপ্ন পূর্ণ হয়েছে, আর ছেলের বদলে এক মহান কুরবানি দিলেন।","title":"ইবরাহিম — কুরবানি ও পুত্র","titleBn":"ইবরাহিম — কুরবানি ও পুত্র","tradition":"quran"},{"context":"ইবরাহিম ও ইসমাইল মক্কায় ঘরের ভিত্তি তুললেন এবং দোয়া করলেন আল্লাহ যেন তা কবুল করেন ও তাঁদের বংশধরদের আত্মসমর্পণকারী জাতি বানান।","id":"s12","lessons":["আল্লাহর জন্য নির্মাণ শেষ হয় দোয়া দিয়ে, গর্ব দিয়ে নয়।","ইবাদতের ঘর শুরু হয় পরিবারের একসাথে কাজ দিয়ে।","প্রতিটি ভালো কাজ শেষ হওয়া উচিত কবুল হওয়ার দোয়া দিয়ে।"],"prophet":{"ar":"إبراهيم","bn":"ইবরাহিম","en":"ইবরাহিম"},"quran":[{"name":"Al-Baqarah","surah":2,"verses":"127–129"}],"readingMinutes":4,"summary":"ইবরাহিম ও তাঁর ছেলে ইসমাইল ঘরের ভিত্তি তুললেন এবং দোয়া করলেন আল্লাহ যেন তাঁদের কাজ কবুল করেন, বংশধরদের রীতিনীতি শেখান এবং তাঁদের কাছে একজন রাসূল পাঠান যিনি নিদর্শন পড়ে শোনাবেন ও তাঁদের পবিত্র করবেন।","title":"ইবরাহিম — ঘর নির্মাণ","titleBn":"ইবরাহিম — ঘর নির্মাণ","tradition":"quran"},{"context":"লুত তাঁর জাতিকে ডাকলেন, যারা লজ্জাজনক কাজে ডুবে গিয়েছিল — আল্লাহকে ভয় করতে ও দুর্নীতি ছাড়তে বললেন।","id":"s13","lessons":["নবীকে নিজের জাতির অন্যায়ের বিরুদ্ধেও কথা বলতে হয়।","মেহমানদারি ও অতিথিকে সম্মান করা পবিত্র দায়িত্ব।","দুর্নীতি পূর্ণ হলে চলে যাওয়া পলায়ন নয়, আনুগত্য।"],"prophet":{"ar":"لوط","bn":"লুত","en":"লুত"},"quran":[{"name":"Al-A'raf","surah":7,"verses":"80–84"},{"name":"Hud","surah":11,"verses":"77–83"}],"readingMinutes":4,"summary":"লুত তাঁর জাতিকে তাদের লজ্জাজনক কাজের বিরুদ্ধে সতর্ক করলেন, কিন্তু তারা তাঁকে বের করে দেওয়ার হুমকি দিল। ফেরেশতারা মানুষের রূপে তাঁর কাছে এলেন; তাঁর জাতি তাঁর বাড়িতে ছুটে এলো, তিনি তাদের অতিথিদের সম্মান করতে অনুরোধ করলেন। ভোরে তাঁর শহর উল্টে দেওয়া হলো, আর লুত ও মুমিনরা বেঁচে গেলেন।","title":"লুত — তাঁর জাতির প্রতি আহ্বান","titleBn":"লুত — তাঁর জাতির প্রতি আহ্বান","tradition":"quran"},{"context":"ইসমাইলকে তাঁর মা হাজেরাসহ এক অনুর্বর উপত্যকায় রেখে যাওয়া হয়েছিল — ধ্রুপদী বর্ণনায় এটাই মক্কা ও জমজম কূপের কাহিনীর অংশ।","id":"s14","lessons":["যেখানে কোনো উপায় দেখা যায় না, সেখানেও রিজিক আসতে পারে।","মায়ের খোঁজ ও শিশুর তৃষ্ণা ইবাদতের রীতিতে স্মরণীয়।","আল্লাহর ওপর ভরসা অনুর্বর উপত্যকাকে শহর বানায়।"],"prophet":{"ar":"إسماعيل","bn":"ইসমাইল","en":"ইসমাইল"},"quran":[{"name":"Al-Baqarah","surah":2,"verses":"127"},{"name":"Ibrahim","surah":14,"verses":"37"}],"readingMinutes":4,"summary":"কুরআনে ইবরাহিমের দোয়া আছে সেই উপত্যকার জন্য যেখানে তিনি পরিবারের একাংশকে রেখেছিলেন — যেন তা নিরাপদ ও রিজিকপ্রাপ্ত হয়। ধ্রুপদী আলেমরা বর্ণনা করেন কীভাবে হাজেরা দুই পাহাড়ের মাঝে খুঁজেছিলেন ও জমজম কূপ ফুটে উঠেছিল — এই বিস্তারিত বর্ণনা ঐতিহ্য থেকে, এই আয়াতগুলো থেকে নয়।","title":"ইসমাইল — উপত্যকা ও কূপ","titleBn":"ইসমাইল — উপত্যকা ও কূপ","tradition":"quran+scholarship"},{"context":"ইসহাকের সুসংবাদ দেওয়া হয়েছিল ইবরাহিম ও সারাকে তাঁদের বার্ধক্যে — এমন এক সুসংবাদ যা তাঁদের কাছে অসম্ভব মনে হয়েছিল।","id":"s15","lessons":["আল্লাহর প্রতিশ্রুতি মানুষের বয়সের হিসাবে বাঁধা নয়।","সুসংবাদ আসতে পারে যখন আশা শেষ মনে হয়।","সন্তানের জন্য কৃতজ্ঞতা নিজেই নিয়ামতের অংশ।"],"prophet":{"ar":"إسحاق","bn":"ইসহাক","en":"ইসহাক"},"quran":[{"name":"Hud","surah":11,"verses":"69–73"},{"name":"As-Saffat","surah":37,"verses":"112–113"}],"readingMinutes":3,"summary":"ফেরেশতারা ইবরাহিমের কাছে এসে এক জ্ঞানী পুত্রের সুসংবাদ দিলেন। সারা অবাক হয়ে হাসলেন, কারণ তিনি বৃদ্ধা ছিলেন আর স্বামীও বয়স্ক। ফেরেশতারা বললেন এটাই আল্লাহর সিদ্ধান্ত — আর ইসহাক জন্ম নিলেন, সৎকর্মশীলদের মধ্যে একজন নবী।","title":"ইসহাক — সুসংবাদ","titleBn":"ইসহাক — সুসংবাদ","tradition":"quran"},{"context":"ইয়াকুব, ইউসুফের বাবা, প্রিয় ছেলেকে হারানো ও পরে দৃষ্টিশক্তি হারানো সহ্য করলেন, তবু আল্লাহর ওপর ভরসা ছাড়লেন না।","id":"s16","lessons":["দুঃখ ও ঈমান একই হৃদয়ে থাকতে পারে।","বাবার ধৈর্য তিক্ততা ছাড়া কয়েক দশক ধরে চলতে পারে।","আল্লাহর ওপর আশা সময়ের সাথে শেষ হয় না।"],"prophet":{"ar":"يعقوب","bn":"ইয়াকুব","en":"ইয়াকুব"},"quran":[{"name":"Yusuf","surah":12,"verses":"83–87"},{"name":"Al-Baqarah","surah":2,"verses":"132–133"}],"readingMinutes":4,"summary":"ইউসুফ হারিয়ে গেলে ইয়াকুব কাঁদতে কাঁদতে দৃষ্টি হারালেন, তবু ছেলেদের বললেন আল্লাহর স্বস্তি থেকে কখনো নিরাশ হয়ো না। বহু বছর পর সত্য প্রকাশ পেলে তিনি ছেলেদের ক্ষমা করে তাঁদের জন্য দোয়া করলেন, আর পরিবার মিসরে আবার এক হলো।","title":"ইয়াকুব — ধৈর্য ও ভরসা","titleBn":"ইয়াকুব — ধৈর্য ও ভরসা","tradition":"quran"},{"context":"ছোটবেলায় ইউসুফ স্বপ্নে দেখলেন এগারোটি তারা, সূর্য ও চাঁদ তাঁকে সিজদা করছে। বাবা তাঁকে ভাইদের বলতে নিষেধ করলেন।","id":"s17","lessons":["বড় স্বপ্ন রক্ষা করতে হয়, প্রচার করতে নয়।","হিংসা প্রায়ই সবচেয়ে কাছের মানুষদের মাঝে শুরু হয়।","বাবার সতর্কবাণী নিজেই এক ধরনের সুরক্ষা।"],"prophet":{"ar":"يوسف","bn":"ইউসুফ","en":"ইউসুফ"},"quran":[{"name":"Yusuf","surah":12,"verses":"4–6"}],"readingMinutes":3,"summary":"ইউসুফ বাবা ইয়াকুবকে বললেন তিনি দেখেছেন এগারোটি তারা, সূর্য ও চাঁদ তাঁকে সিজদা করছে। ইয়াকুব স্বপ্নের অর্থ বুঝলেন, তাঁকে ভাইদের বলতে নিষেধ করলেন যেন হিংসা না জাগে, আর বললেন আল্লাহ তাঁর প্রতি নিয়ামত পূর্ণ করবেন।","title":"ইউসুফ — স্বপ্ন","titleBn":"ইউসুফ — স্বপ্ন","tradition":"quran"},{"context":"ইউসুফের ভাইরা, বাবার ভালোবাসার প্রতি হিংসায়, তাঁকে কূপে ফেলে বাবাকে বলল নেকড়ে তাঁকে খেয়েছে।","id":"s18","lessons":["হিংসা ভাইদের অচেনা বানাতে পারে।","মিথ্যার প্রমাণ লাগে; সত্যের শুধু ধৈর্য লাগে।","কূপের ভেতরেও একটি ছেলে আল্লাহর হেফাজতে থাকতে পারে।"],"prophet":{"ar":"يوسف","bn":"ইউসুফ","en":"ইউসুফ"},"quran":[{"name":"Yusuf","surah":12,"verses":"7–22"}],"readingMinutes":5,"summary":"ভাইরা ইউসুফকে দূরে নিয়ে কূপে ফেলল, আর তাঁর জামায় মিথ্যা রক্ত মাখাল। পাশ দিয়ে যাওয়া এক কাফেলা তাঁকে তুলে মিসরে অল্প দামে বেচে দিল। মিসরের মালিকের বাড়িতে ইউসুফ জ্ঞান ও সৌন্দর্যে বড় হলেন।","title":"ইউসুফ — কূপ ও কাফেলা","titleBn":"ইউসুফ — কূপ ও কাফেলা","tradition":"quran"},{"context":"মিসরে ইউসুফ মালিকের বাড়িতে প্রলোভন প্রত্যাখ্যান করলেন এবং মিথ্যা অভিযোগে কারাবন্দি হলেন, যেখানে বহু বছর রইলেন।","id":"s19","lessons":["পবিত্রতা দুর্বলতা নয়, শক্তি।","মিথ্যা অভিযোগও শেষ পর্যন্ত সম্মানে পরিণত হতে পারে।","কারাগার ধৈর্যশীল হৃদয়ের জন্য বিদ্যালয় হতে পারে।"],"prophet":{"ar":"يوسف","bn":"ইউসুফ","en":"ইউসুফ"},"quran":[{"name":"Yusuf","surah":12,"verses":"23–35"}],"readingMinutes":5,"summary":"মালিকের স্ত্রী ইউসুফকে প্রলুব্ধ করতে চাইলেন; তিনি অস্বীকার করে পালালেন, আর ছেঁড়া জামা তাঁর নির্দোষতা প্রমাণ করল — তবু সুনাম রক্ষার জন্য তাঁকে কারাগারে পাঠানো হলো। কারাগারে তিনি সহবন্দিদের আল্লাহর দিকে ডাকলেন এবং এমন স্পষ্টভাবে তাঁদের স্বপ্নের ব্যাখ্যা দিলেন যে তারা বিস্মিত হলো।","title":"ইউসুফ — মিসরে পরীক্ষা","titleBn":"ইউসুফ — মিসরে পরীক্ষা","tradition":"quran"},{"context":"বাদশাহ স্বপ্নে দেখলেন সাতটি মোটা গাভীকে সাতটি রোগা গাভী খাচ্ছে, আর সাতটি সবুজ শিষ ও সাতটি শুকনো শিষ। ইউসুফ স্বপ্নের ব্যাখ্যা দিলেন ও দুর্ভিক্ষের পরিকল্পনা করলেন।","id":"s20","lessons":["জ্ঞান সবচেয়ে মূল্যবান যখন তা মানুষের প্রয়োজনে কাজে লাগে।","কষ্টের জন্য পরিকল্পনা করা ভরসার অভাব নয়, তারই অংশ।","জনকল্যাণে ব্যবহৃত প্রতিভা জনগণের আমানত হয়ে যায়।"],"prophet":{"ar":"يوسف","bn":"ইউসুফ","en":"ইউসুফ"},"quran":[{"name":"Yusuf","surah":12,"verses":"36–49"}],"readingMinutes":5,"summary":"বাদশাহর স্বপ্ন সভাসদদের হতবাক করলে কারাগারে থাকা ইউসুফ তার ব্যাখ্যা দিলেন: সাত বছর প্রাচুর্যের পর সাত বছর দুর্ভিক্ষ আসবে, আর ভালো বছরগুলোতে শস্য জমিয়ে রাখার পরামর্শ দিলেন। বাদশাহ মুগ্ধ হয়ে তাঁকে ডেকে শস্যভাণ্ডারের দায়িত্ব দিলেন।","title":"ইউসুফ — স্বপ্নের ব্যাখ্যা","titleBn":"ইউসুফ — স্বপ্নের ব্যাখ্যা","tradition":"quran"},{"context":"দুর্ভিক্ষের সময় ইউসুফের ভাইরা শস্যের জন্য মিসরে এলো। তিনি তাঁদের পরীক্ষা করলেন, নিজের পরিচয় দিলেন এবং সম্পূর্ণ ক্ষমা করলেন।","id":"s21","lessons":["ক্ষমতার পর ক্ষমা করাই শক্তির সর্বোচ্চ রূপ।","অন্যায়কারীর সম্মান নষ্ট না করেও ভুল শোধরানো যায়।","বিশ্বাসঘাতকতার পরও পারিবারিক বন্ধন টিকে থাকতে পারে।"],"prophet":{"ar":"يوسف","bn":"ইউসুফ","en":"ইউসুফ"},"quran":[{"name":"Yusuf","surah":12,"verses":"58–101"}],"readingMinutes":6,"summary":"ভাইরা শস্য নিতে এসে তাঁদের সামনের মন্ত্রীকে চিনতে পারল না। ইউসুফ তাঁদের পরীক্ষা করলেন, তারপর নিজের পরিচয় দিলেন: 'আমি ইউসুফ, আর এ আমার ভাই।' তিনি কোনো তিরস্কার ছাড়াই ক্ষমা করলেন, বাবা-মাকে মিসরে আনলেন, আর স্বপ্ন পূর্ণ হওয়ার জন্য আল্লাহর শুকরিয়া আদায় করলেন।","title":"ইউসুফ — পুনর্মিলন ও ক্ষমা","titleBn":"ইউসুফ — পুনর্মিলন ও ক্ষমা","tradition":"quran"},{"context":"আইয়ুব সম্পদ, সন্তান ও স্বাস্থ্য হারালেন, তবু ধৈর্য ধরে আল্লাহর কাছে দোয়া করলেন।","id":"s22","lessons":["ধৈর্য মানে ব্যথা না থাকা নয়, ব্যথার মধ্যেও টিকে থাকা।","বিপদে আল্লাহকে ডাকা নিজেই ইবাদত।","স্বস্তি এলে তা হারানো জিনিসের চেয়েও বেশি হতে পারে।"],"prophet":{"ar":"أيوب","bn":"আইয়ুব","en":"আইয়ুব"},"quran":[{"name":"Al-Anbiya","surah":21,"verses":"83–84"},{"name":"Sad","surah":38,"verses":"41–44"}],"readingMinutes":4,"summary":"আইয়ুব দীর্ঘ বিপদ সহ্য করে আল্লাহকে ডাকলেন — কষ্ট তাঁকে স্পর্শ করেছে, আর আল্লাহ সবচেয়ে দয়ালু। আল্লাহ তাঁর ডাকে সাড়া দিলেন, কষ্ট দূর করলেন, আর পরিবার ও সম্পদ ফিরিয়ে দিলেন — দয়া হিসেবে এবং ইবাদতকারীদের জন্য স্মরণিকা হিসেবে।","title":"আইয়ুব — বিপদে ধৈর্য","titleBn":"আইয়ুব — বিপদে ধৈর্য","tradition":"quran"},{"context":"শুয়াইবকে মাদইয়ানবাসীর কাছে পাঠানো হয়েছিল, যারা ব্যবসায় প্রতারণা করত ও রাস্তা আটকাত। তিনি ন্যায্য মাপ ও সৎ ব্যবসার দিকে ডাকলেন।","id":"s23","lessons":["ব্যবসায় সততা ঈমানের অংশ, তা থেকে আলাদা নয়।","ক্রেতাকে ঠকানো দুর্নীতি, মাপ যত ছোটই হোক।","জাতির অর্থনীতি তার নৈতিকতার প্রতিফলন।"],"prophet":{"ar":"شعيب","bn":"শুয়াইব","en":"শুয়াইব"},"quran":[{"name":"Hud","surah":11,"verses":"84–95"},{"name":"Al-A'raf","surah":7,"verses":"85–93"}],"readingMinutes":4,"summary":"শুয়াইব তাঁর জাতিকে পূর্ণ মাপ ও ওজন দিতে, মানুষকে ঠকাতে না এবং দুর্নীতি না ছড়াতে বললেন। তারা তাঁকে ঠাট্টা করল ও হুমকি দিল, কিন্তু তিনি অবিচল রইলেন। এক প্রচণ্ড শব্দ অস্বীকারকারীদের পাকড়াও করল, আর শুয়াইব ও মুমিনরা বেঁচে গেলেন।","title":"শুয়াইব — সঠিক মাপ","titleBn":"শুয়াইব — সঠিক মাপ","tradition":"quran"},{"context":"মুসা মাদইয়ানে ছাগল চরাতে গিয়ে পাহাড়ে আগুন দেখলেন এবং বরকতময় উপত্যকা থেকে আল্লাহর বাণী শুনলেন।","id":"s24","lessons":["ডাক আসতে পারে সাধারণ কাজের মাঝেই।","পবিত্র কথার আগে বাধা — এমনকি জুতোও — খুলে রাখতে হয়।","আল্লাহ 'ভয় পেয়ো না' বললে ভয় শক্তিতে পরিণত হয়।"],"prophet":{"ar":"موسى","bn":"মুসা","en":"মুসা"},"quran":[{"name":"Ta-Ha","surah":20,"verses":"9–36"},{"name":"Al-Qasas","surah":28,"verses":"29–35"}],"readingMinutes":5,"summary":"মুসা আগুন দেখে সেদিকে গেলেন — হয়তো একটি অঙ্গার বা পথনির্দেশ পাবেন। আগুন থেকে আওয়াজ এলো: 'আমিই আল্লাহ।' তাঁর লাঠি সাপ হয়ে গেল, হাত সাদা ঝকঝকে হলো। তিনি ভাই হারুনকে সাহায্যকারী হিসেবে চাইলেন, আল্লাহ তা মঞ্জুর করলেন এবং দুজনকে ফেরাউনের কাছে পাঠালেন।","title":"মুসা — জ্বলন্ত ঝোপ","titleBn":"মুসা — জ্বলন্ত ঝোপ","tradition":"quran"},{"context":"মুসা ও হারুন ফেরাউনের মুখোমুখি হলেন, যে নিজেকে উপাস্য দাবি করত ও বনি ইসরাইলকে দাস বানিয়েছিল। ফেরাউনের জাদুকরদের সাথে প্রতিযোগিতা শেষ হলো জাদুকরদের ঈমান আনা দিয়ে।","id":"s25","lessons":["সত্য বলতে ফেরাউনের অনুমতি লাগে না।","ভাড়া করা প্রতিপক্ষও সত্য দেখলে চিনতে পারে।","অত্যাচারের প্রথম জবাব সত্যকে ঠাট্টা, তারপর শক্তি।"],"prophet":{"ar":"موسى","bn":"মুসা","en":"মুসা"},"quran":[{"name":"Al-A'raf","surah":7,"verses":"103–126"},{"name":"Ta-Ha","surah":20,"verses":"56–73"}],"readingMinutes":5,"summary":"মুসা ফেরাউনকে নিদর্শন দেখালেন — সাপ হয়ে যাওয়া লাঠি ও ঝকঝকে হাত — কিন্তু ফেরাউন তাকে জাদু বলে তাঁর জাদুকরদের ডাকল। তাদের দড়ি ও লাঠি নড়তে লাগল, কিন্তু মুসার লাঠি সেগুলো গিলে ফেলল। জাদুকররা সিজদায় পড়ে ঈমান আনল, যদিও ফেরাউন তাদের শাস্তির হুমকি দিল।","title":"মুসা — ফেরাউনের সামনে","titleBn":"মুসা — ফেরাউনের সামনে","tradition":"quran"},{"context":"ফেরাউনের বাহিনী বনি ইসরাইলকে সমুদ্র পর্যন্ত তাড়া করল। আল্লাহ পানি ভাগ করে দিলেন, বনি ইসরাইল পার হলো, আর ফেরাউনের বাহিনী ডুবল।","id":"s26","lessons":["সব রাস্তা বন্ধ হলে সমুদ্র নিজেই খুলে যেতে পারে।","তাড়াকারীর শক্তি সেখানেই শেষ যেখানে আল্লাহর আদেশ শুরু।","একই পানিতে মুক্তি ও ধ্বংস দুটোই হতে পারে।"],"prophet":{"ar":"موسى","bn":"মুসা","en":"মুসা"},"quran":[{"name":"Ta-Ha","surah":20,"verses":"77–82"},{"name":"Ash-Shu'ara","surah":26,"verses":"52–68"}],"readingMinutes":5,"summary":"আল্লাহর আদেশে মুসা তাঁর জাতিকে রাতে বের করে নিয়ে গেলেন। সমুদ্রের ধারে, পেছনে ফেরাউনের বাহিনী দেখে জাতি হতাশ হলো, কিন্তু মুসা সমুদ্রে আঘাত করলেন আর তা শুকনো পথে ভাগ হয়ে গেল। বনি ইসরাইল নিরাপদে পার হলো; পিছু নেওয়া ফেরাউন ও তার বাহিনী ডুবে গেল।","title":"মুসা — সমুদ্র পারাপার","titleBn":"মুসা — সমুদ্র পারাপার","tradition":"quran"},{"context":"মুসা পাহাড়ে ফলক নিতে গেলে তাঁর জাতির কিছু লোক সোনার বাছুর বানিয়ে তার পূজা শুরু করল।","id":"s27","lessons":["নেতা অনুপস্থিত হলেই জাতি পিছলে যেতে পারে।","ধৈর্য শেষ হলে সোনাও মূর্তি হয়ে যায়।","নেতার রাগের পর থাকা উচিত সুপারিশ, পরিত্যাগ নয়।"],"prophet":{"ar":"موسى","bn":"মুসা","en":"মুসা"},"quran":[{"name":"Ta-Ha","surah":20,"verses":"83–98"},{"name":"Al-A'raf","surah":7,"verses":"148–154"}],"readingMinutes":5,"summary":"মুসা চল্লিশ রাতের জন্য পাহাড়ে গেলেন। তাঁর অনুপস্থিতিতে সামিরি জাতির সোনা দিয়ে একটি বাছুর বানাল, অনেকে তার পূজা করল। মুসা রাগ নিয়ে ফিরলেন, হারুনকে ধরলেন, তারপর নিজের ও ভাইয়ের জন্য ক্ষমা চেয়ে দোয়া করলেন। বাছুর পুড়িয়ে সমুদ্রে ছড়িয়ে দেওয়া হলো।","title":"মুসা — সোনার বাছুর","titleBn":"মুসা — সোনার বাছুর","tradition":"quran"},{"context":"হারুন, মুসার ভাই, মিশনে অংশীদার ছিলেন: তিনি মুসার পক্ষে কথা বলতেন, জাতির সাথে থাকতেন এবং চাপের মুখে ধৈর্য ধরতেন।","id":"s28","lessons":["সহযোগীর ভূমিকা নিজেই নবুয়তের সম্মান।","সত্যের পক্ষে কথা বলতে নেতৃত্বের চেয়ে আলাদা সাহস লাগে।","চাপের মুখে সংযম শক্তি প্রয়োগের চেয়ে জ্ঞানী হতে পারে।"],"prophet":{"ar":"هارون","bn":"হারুন","en":"হারুন"},"quran":[{"name":"Ta-Ha","surah":20,"verses":"29–36"},{"name":"Al-A'raf","surah":7,"verses":"142"}],"readingMinutes":4,"summary":"মুসা আল্লাহর কাছে হারুনকে তাঁর মন্ত্রী বানাতে চাইলেন — যেন তিনি শক্তি পান ও কাজ ভাগ করে নিতে পারেন। হারুন ফেরাউনের সামনে মুসার পাশে দাঁড়ালেন এবং মুসা পাহাড়ে গেলে জাতির সাথে থেকে বাছুরের দিকে ঝুঁকে যাওয়া লোকদের ধৈর্য ধরতে বললেন।","title":"হারুন — ভাই ও সহযোগী","titleBn":"হারুন — ভাই ও সহযোগী","tradition":"quran"},{"context":"দাউদ, এক রাখাল থেকে বাদশাহ হলেন — তাঁকে জাবুর দেওয়া হয়েছিল এবং এমন সুন্দর কণ্ঠ যে পাহাড় ও পাখি তাঁর প্রশংসায় যোগ দিত।","id":"s29","lessons":["নেতৃত্ব ও ইবাদত একসাথে থাকে।","ন্যায় প্রমাণ দিয়ে বিচার করতে হয়, নিজের বিরুদ্ধে গেলেও।","সুন্দর কণ্ঠ আমানত — প্রশংসায় ব্যবহার করতে হয়, গর্বে নয়।"],"prophet":{"ar":"داود","bn":"দাউদ","en":"দাউদ"},"quran":[{"name":"Sad","surah":38,"verses":"17–26"},{"name":"Al-Baqarah","surah":2,"verses":"251"}],"readingMinutes":4,"summary":"দাউদকে জ্ঞান, রাজত্ব ও জাবুর দেওয়া হয়েছিল। কুরআনে তাঁর তওবার কথা আছে — দুই বিবাদীর মামলায় বিচার করার পর — এবং কীভাবে আল্লাহ তাঁর রাজত্ব শক্তিশালী করলেন। কুরআনের চিত্রে তাঁর প্রশংসায় পাহাড় ও পাখি যোগ দিত।","title":"দাউদ — জাবুরের নবী ও বাদশাহ","titleBn":"দাউদ — জাবুরের নবী ও বাদশাহ","tradition":"quran"},{"context":"সুলাইমান পাখির ভাষা বুঝতেন এবং পিঁপড়ের উপত্যকা পার হওয়ার সময় একটি পিঁপড়ার সতর্কবাণী শুনে হাসলেন।","id":"s30","lessons":["ক্ষমতা তখনই পূর্ণ যখন তা ক্ষুদ্রতম কণ্ঠও শোনে।","ছোট প্রাণীর প্রতি হাসি বড় হৃদয়ের পরিচয়।","নিয়ামতের জন্য কৃতজ্ঞতা নিয়ামতেরই অংশ।"],"prophet":{"ar":"سليمان","bn":"সুলাইমান","en":"সুলাইমান"},"quran":[{"name":"An-Naml","surah":27,"verses":"15–19"}],"readingMinutes":3,"summary":"সুলাইমান দাউদের উত্তরাধিকারী হলেন, পাখির ভাষা শিখলেন এবং জিন, মানুষ ও পাখির বাহিনী নিয়ে চললেন। পিঁপড়ের উপত্যকায় তিনি শুনলেন একটি পিঁপড়া সঙ্গীদের সতর্ক করছে — সুলাইমানের বাহিনী অজান্তে তাদের পিষে ফেলার আগেই গর্তে ঢুকতে। তিনি হেসে আল্লাহর নিয়ামতের শুকরিয়া আদায় করলেন।","title":"সুলাইমান — পিঁপড়ের উপত্যকা","titleBn":"সুলাইমান — পিঁপড়ের উপত্যকা","tradition":"quran"},{"context":"সুলাইমান খবর পেলেন সাবার এক রানি সূর্যের পূজা করেন। তিনি তাঁকে আল্লাহর দিকে আমন্ত্রণ জানালেন, তিনি এলেন ও আত্মসমর্পণ করলেন।","id":"s31","lessons":["কূটনীতি শক্তির আগে আসতে পারে, প্রায়ই তার জায়গা নিতে পারে।","জ্ঞানী শাসক খবরে কাজ করার আগে তা যাচাই করেন।","সত্যের কাছে আত্মসমর্পণ পরাজয় নয়, মর্যাদা।"],"prophet":{"ar":"سليمان","bn":"সুলাইমান","en":"সুলাইমান"},"quran":[{"name":"An-Naml","surah":27,"verses":"20–44"}],"readingMinutes":5,"summary":"হুদহুদ পাখি সুলাইমানকে সাবার রানির খবর দিল — তাঁর জাতি সূর্যের পূজা করত। সুলাইমান তাঁকে আত্মসমর্পণের আমন্ত্রণ জানিয়ে চিঠি পাঠালেন। তিনি এলেন, নিদর্শন চিনলেন, এবং কাচের প্রাসাদের মেঝেকে পানি ভেবে ভুল করার পর সুলাইমানের সাথে আল্লাহর কাছে আত্মসমর্পণ ঘোষণা করলেন।","title":"সুলাইমান — সাবার রানি","titleBn":"সুলাইমান — সাবার রানি","tradition":"quran"},{"context":"ইলিয়াস তাঁর জাতিকে ডাকলেন, যারা বাল দেবতার পূজা করত — আল্লাহর দিকে ফিরতে বললেন, কিন্তু তারা তাঁকে প্রত্যাখ্যান করল।","id":"s32","lessons":["উত্তরাধিকারসূত্রে পাওয়া মূর্তি থেকে মানুষকে ফেরানো একাকী কাজ।","নবীর সাফল্য ভিড়ের সাড়া দিয়ে মাপা হয় না।","প্রত্যাখ্যানকারী জাতির প্রতি ধৈর্য নিজেই বিশ্বস্ততা।"],"prophet":{"ar":"إلياس","bn":"ইলিয়াস","en":"ইলিয়াস"},"quran":[{"name":"As-Saffat","surah":37,"verses":"123–132"}],"readingMinutes":3,"summary":"ইলিয়াস তাঁর জাতিকে আল্লাহকে ভয় করতে ও বালের পূজা ছাড়তে বললেন, কিন্তু তারা তাঁকে মিথ্যাবাদী বলল। কুরআনে আছে পরবর্তী প্রজন্মের মাঝে তাঁর ভালো নাম থেকে গেল, আর যারা বাণী প্রত্যাখ্যান করল তারা তার পরিণতি ভোগ করল।","title":"ইলিয়াস — তাঁর জাতির প্রতি আহ্বান","titleBn":"ইলিয়াস — তাঁর জাতির প্রতি আহ্বান","tradition":"quran"},{"context":"আল-ইয়াসাকে কুরআনে সৎকর্মশীল নবীদের মধ্যে গোনা হয়েছে — হেদায়েতের ধারায় একজন উত্তরসূরি।","id":"s33","lessons":["পূর্বসূরির কাজ চালিয়ে যাওয়া নিজেই নবুয়তের কাজ।","কুরআন কিছু নবীকে নাম দিয়ে সম্মানিত করেছে, দীর্ঘ কাহিনী ছাড়াই।","অলিখিত জীবনে অবিচল থাকাও আল্লাহর কাছে লেখা থাকে।"],"prophet":{"ar":"اليسع","bn":"আল-ইয়াসা","en":"আল-ইয়াসা"},"quran":[{"name":"Sad","surah":38,"verses":"48"},{"name":"Al-An'am","surah":6,"verses":"86"}],"readingMinutes":3,"summary":"আল-ইয়াসাকে কুরআনে উত্তম ও সৎকর্মশীলদের মধ্যে উল্লেখ করা হয়েছে, ইসমাইল ও জুলকিফলের পাশে। তাঁর সম্পর্কে কুরআনে কোনো দীর্ঘ কাহিনী দেওয়া হয়নি; ধ্রুপদী আলেমরা তাঁকে ইলিয়াসের হেদায়েত বহনকারী উত্তরসূরি হিসেবে রাখেন।","title":"আল-ইয়াসা — উত্তরসূরি","titleBn":"আল-ইয়াসা — উত্তরসূরি","tradition":"quran+scholarship"},{"context":"ইউনুস শাস্তি আসার আগেই রাগ করে তাঁর জাতিকে ছেড়ে চলে গেলেন, এক বড় মাছ তাঁকে গিলে ফেলল, আর তিনি অন্ধকার থেকে ডাকলেন।","id":"s34","lessons":["রাগ করে কাজ ছেড়ে যাওয়া নিজেই তওবা করার মতো ভুল।","সমুদ্র, রাত ও পেটের অন্ধকার আন্তরিক ডাক লুকাতে পারে না।","পুরো শহরের তওবা শাস্তি ফিরিয়ে দিতে পারে।"],"prophet":{"ar":"يونس","bn":"ইউনুস","en":"ইউনুস"},"quran":[{"name":"As-Saffat","surah":37,"verses":"139–148"},{"name":"Al-Anbiya","surah":21,"verses":"87–88"}],"readingMinutes":5,"summary":"ইউনুস অনুমতি আসার আগেই জাতিকে ছেড়ে বোঝাই জাহাজে উঠলেন। সমুদ্রে ফেলে দেওয়া হলে এক বড় মাছ তাঁকে গিলল, তিনি অন্ধকার থেকে আল্লাহর প্রশংসা করে নিজের ভুল স্বীকার করে ডাকলেন। তাঁকে তীরে ফেলা হলো, আর তাঁর জাতি — যারা ঈমান এনেছিল — অবকাশ পেল।","title":"ইউনুস — মাছের মানুষ","titleBn":"ইউনুস — মাছের মানুষ","tradition":"quran"},{"context":"জুলকিফলকে কুরআনে ধৈর্যশীল ও সৎকর্মশীলদের মধ্যে গোনা হয়েছে, যদিও তাঁর সম্পর্কে কোনো কাহিনী বর্ণনা করা হয়নি।","id":"s35","lessons":["ধৈর্য শুধু অনুভূতি নয়, একটি মর্যাদা।","কিছু সৎকর্মশীল আল্লাহর কাছে শুধু নামেই পরিচিত।","আমানত বিশ্বস্তভাবে রক্ষা করা নবুয়তের কাজেরই রূপ।"],"prophet":{"ar":"ذو الكفل","bn":"জুলকিফল","en":"জুলকিফল"},"quran":[{"name":"Al-Anbiya","surah":21,"verses":"85–86"},{"name":"Sad","surah":38,"verses":"48"}],"readingMinutes":3,"summary":"জুলকিফলকে কুরআনে ধৈর্যশীল ও সৎকর্মশীলদের মধ্যে উল্লেখ করা হয়েছে, ইসমাইল ও ইদরিসের সাথে। তাঁর সম্পর্কে কুরআনে আর কোনো বর্ণনা দেওয়া হয়নি; ধ্রুপদী আলেমরা নানা পরিচয় দিয়েছেন, যা কুরআনের পাঠ দিয়ে চূড়ান্ত হয় না।","title":"জুলকিফল — ধৈর্যশীল","titleBn":"জুলকিফল — ধৈর্যশীল","tradition":"quran+scholarship"},{"context":"জাকারিয়া, বৃদ্ধ ও নিঃসন্তান, গোপনে একজন উত্তরাধিকারীর জন্য দোয়া করলেন, আর তাঁকে ইয়াহিয়া দেওয়া হলো।","id":"s36","lessons":["গোপন দোয়া প্রকাশ্য দোয়ার চেয়ে কম শক্তিশালী নয়।","বার্ধক্য আল্লাহর দানের দরজা বন্ধ করে না।","কবুল হওয়া দোয়ার জবাব হওয়া উচিত আরও বেশি ইবাদত, কম নয়।"],"prophet":{"ar":"زكريا","bn":"জাকারিয়া","en":"জাকারিয়া"},"quran":[{"name":"Maryam","surah":19,"verses":"2–15"},{"name":"Al-Anbiya","surah":21,"verses":"89–90"}],"readingMinutes":4,"summary":"জাকারিয়া গোপনে আল্লাহকে ডাকলেন, বার্ধক্য ও স্ত্রীর বন্ধ্যাত্ব সত্ত্বেও একজন উত্তরাধিকারী চাইলেন। ফেরেশতারা তাঁকে ইয়াহিয়ার সুসংবাদ দিলেন — এমন একটি নাম যা আগে কাউকে দেওয়া হয়নি। তিনি একটি নিদর্শন চাইলে বলা হলো তিনি সুস্থ থেকেও তিন রাত মানুষের সাথে কথা বলতে পারবেন না।","title":"জাকারিয়া — কবুল হওয়া দোয়া","titleBn":"জাকারিয়া — কবুল হওয়া দোয়া","tradition":"quran"},{"context":"ইয়াহিয়া, জাকারিয়ার ছেলে, ছোটবেলাতেই জ্ঞান পেয়েছিলেন — তাঁকে পবিত্র, বাবা-মায়ের প্রতি কর্তব্যপরায়ণ ও অহংকারমুক্ত বলা হয়েছে।","id":"s37","lessons":["পবিত্র হৃদয়ে জ্ঞান তাড়াতাড়ি আসতে পারে।","বাবা-মায়ের প্রতি কর্তব্যপরায়ণতা নবুয়তের চরিত্রের অংশ।","পবিত্রতা ও বিনয় দুর্বলতা নয়, শক্তি।"],"prophet":{"ar":"يحيى","bn":"ইয়াহিয়া","en":"ইয়াহিয়া"},"quran":[{"name":"Maryam","surah":19,"verses":"12–15"}],"readingMinutes":3,"summary":"কুরআনে আছে ইয়াহিয়াকে ছোটবেলাতেই জ্ঞান দেওয়া হয়েছিল, আর তাঁকে দয়ালু, পবিত্র, বাবা-মায়ের প্রতি কর্তব্যপরায়ণ এবং অহংকারী বা অবাধ্য নয় বলে বর্ণনা করা হয়েছে। তাঁর জন্মদিনে, মৃত্যুদিনে ও জীবিত পুনরুত্থানের দিনে তাঁর ওপর শান্তি ঘোষণা করা হয়েছে।","title":"ইয়াহিয়া — পবিত্র নবী","titleBn":"ইয়াহিয়া — পবিত্র নবী","tradition":"quran"},{"context":"মারইয়াম, একা ও প্রসববেদনায়, দুঃখ না করতে বলা হলো; তাঁর জন্য একটি ঝরনা ও পাকা খেজুর দেওয়া হলো, আর শিশুটি দোলনা থেকে কথা বলল।","id":"s38","lessons":["সবচেয়ে একা মানুষের কাছেও রিজিক আসতে পারে।","মায়ের মর্যাদা আল্লাহ নিজে রক্ষা করেন।","মুজিজা চারপাশের কষ্ট দূর করে না।"],"prophet":{"ar":"عيسى","bn":"ঈসা","en":"ঈসা"},"quran":[{"name":"Maryam","surah":19,"verses":"16–36"}],"readingMinutes":5,"summary":"মারইয়াম দূরের এক জায়গায় গিয়ে খেজুর গাছের নিচে সন্তান প্রসব করলেন। তাঁকে গাছের কাণ্ড নাড়াতে বলা হলো পাকা খেজুরের জন্য, আর ঝরনা থেকে পান করতে বলা হলো। জাতি প্রশ্ন করলে শিশু ঈসা দোলনা থেকে কথা বললেন — নিজেকে আল্লাহর বান্দা, কিতাবপ্রাপ্ত নবী ঘোষণা করে।","title":"ঈসা — জন্ম","titleBn":"ঈসা — জন্ম","tradition":"quran"},{"context":"ঈসাকে ইনজিল দেওয়া হয়েছিল, তিনি আল্লাহর অনুমতিতে অন্ধ ও কুষ্ঠরোগীকে সুস্থ করতেন ও মৃতকে জীবিত করতেন, আর জাতিকে এক আল্লাহর ইবাদতের দিকে ডাকতেন।","id":"s39","lessons":["মুজিজা আল্লাহর দিকে ইঙ্গিত করে; তা নিজে লক্ষ্য নয়।","নবীর বাণী এক আল্লাহর ইবাদত।","নিয়ামতের কৃতজ্ঞতা দেখানো হয় তা অন্যের কাজে লাগিয়ে।"],"prophet":{"ar":"عيسى","bn":"ঈসা","en":"ঈসা"},"quran":[{"name":"Al-Imran","surah":3,"verses":"45–59"},{"name":"Al-Ma'idah","surah":5,"verses":"110–120"}],"readingMinutes":5,"summary":"কুরআনে ঈসাকে মাসিহ, আল্লাহর বাণী এবং পবিত্র আত্মা দিয়ে শক্তিশালী বলা হয়েছে। তিনি মাটি দিয়ে পাখি বানিয়ে আল্লাহর অনুমতিতে তাতে প্রাণ দিতেন, অন্ধ ও কুষ্ঠরোগীকে সুস্থ করতেন, মৃতকে জীবিত করতেন — সবই নিদর্শন হিসেবে — আর জাতিকে আল্লাহর ইবাদতের দিকে ডাকতেন, যিনি তাঁর ও তাঁদের রব।","title":"ঈসা — মুজিজা ও বাণী","titleBn":"ঈসা — মুজিজা ও বাণী","tradition":"quran"},{"context":"হেরা গুহায় মুহাম্মদ প্রথম ওহি পেলেন: সৃষ্টিকর্তা রবের নামে পড়ার আদেশ।","id":"s40","lessons":["ওহির প্রথম আদেশ পড়া ও শেখা।","মিশন শুরু হতে পারে নির্জনে, ভিড় থেকে দূরে।","বড় অভিজ্ঞতায় কেঁপে ওঠা মানবিক; তাতে ফিরে আসা ঈমান।"],"prophet":{"ar":"محمد","bn":"মুহাম্মদ","en":"মুহাম্মদ"},"quran":[{"name":"Al-Alaq","surah":96,"verses":"1–5"},{"name":"Al-Muddaththir","surah":74,"verses":"1–7"}],"readingMinutes":4,"summary":"কুরআনের প্রথম নাজিল হওয়া শব্দগুলো ছিল সৃষ্টিকর্তা রবের নামে পড়ার আদেশ — যিনি মানুষকে জমাট রক্ত থেকে সৃষ্টি করেছেন, কলম দিয়ে শিখিয়েছেন, আর মানুষকে শিখিয়েছেন যা সে জানত না। ধ্রুপদী বর্ণনায় এই মুহূর্ত হেরা গুহায়, যেখানে নবী ওহি পেয়ে গভীরভাবে আলোড়িত হয়ে বাড়ি ফিরেছিলেন।","title":"মুহাম্মদ — প্রথম ওহি","titleBn":"মুহাম্মদ — প্রথম ওহি","tradition":"quran+scholarship"}]};
